{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "network_loss",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 2", "claim": "Route-service GET /routes server spans take about 30 s p95 during the incident, versus about 12 ms normally."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name IN ('RouteRepository.findAll','SELECT ts.route','SELECT ts.route_stations','SELECT ts.route_distances') GROUP BY 1", "claim": "Route repository findAll spans stall about 30 s while their DB client spans stay sub-millisecond, and DB calls drop sharply."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(value),2) v FROM abnormal_metrics_sum WHERE service_name='ts-route-service' AND metric LIKE 'db.client.connections%' GROUP BY 1", "claim": "Route-service DB pool shows pending requests and timeouts with zero connections in use, consistent with failed connection setup."},
        {"kind": "metric", "sql": "SELECT strftime(time,'%H:%M') m, sum(value) v FROM abnormal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%ts-route-service-cfc6dbcf7-fzkwd' AND attr_destination LIKE '%mysql-0' GROUP BY 1 ORDER BY 1", "claim": "TCP flag traffic from route-service to mysql jumps from about 150 in normal to about 858 in the incident window."},
        {"kind": "log", "sql": "SELECT level, message, count(*) n FROM abnormal_logs WHERE service_name='ts-route-service' AND level IN ('ERROR','SEVERE') GROUP BY 1,2 ORDER BY 3 DESC", "claim": "Route-service logs 'Communications link failure' and 'Unable to acquire JDBC Connection' with Hikari 30000ms timeouts, only in the incident."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE (service_name='ts-ui-dashboard' AND attr_span_kind='Server') OR (service_name='ts-route-service' AND attr_span_kind='Server') GROUP BY 1,2", "claim": "The user-facing dashboard server p95 rises to about 20 s, matching route-service's roughly 30 s server latency."}
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, c.span_name, p.service_name parent_svc, p.span_name parent_span, count(*) n, round(max(c.duration)/1e6,1) child_max_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' GROUP BY 1,2,3,4", "claim": "Route-plan-service's outgoing calls, including those to route-service, show elevated maximum latency during the incident."}
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, c.span_name, count(*) n, round(max(c.duration)/1e6,1) child_max_ms FROM abnormal_traces c WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' GROUP BY 1,2", "claim": "Travel-plan-service's calls to route-plan-service reach about 262 ms max, with its server spans at about 397 ms."}
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name, c.span_name, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) p95_ms FROM abnormal_traces c WHERE c.service_name='ts-ui-dashboard' AND c.attr_span_kind='Client' GROUP BY 1,2", "claim": "Dashboard calls to travel-plan-service slow to about 2.3 s p95 in normal-to-abnormal comparison, as the chain backs up."}
      ]
    }
